package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.domain.*;
import com.ruoyi.paiflow.mapper.*;
import java.util.*;
import java.util.stream.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 原Factory完成帧为输出预期；此类是隔离Mapper边界，不冒充真实Java Provider。 */
class CompletedOutputSourcesTest {
    static JSONArray cases() throws Exception {var values=new JSONArray();for(String name:List.of("llm-output-projection-golden.json","dynamic-output-projection-golden.json","numeric-output-projection-golden.json"))try(var in=CompletedOutputSourcesTest.class.getResourceAsStream("/fixtures/"+name)){values.addAll(JSON.parseObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("cases"));}return values;}
    @TestFactory Stream<DynamicTest> originalFactoryProjectionGolden() throws Exception{return cases().stream().map(raw->{var c=(JSONObject)raw;return DynamicTest.dynamicTest(c.getString("name"),()->{if(c.getString("name").startsWith("qa-")){var fixture=fixture(c);fixture.sources.verify(fixture.run,fixture.task.getJSONObject("dsl"),fixture.target,fixture.events);}else{var group=c.getJSONArray("sourceFrames");if(group==null)group=c.getJSONArray("sourceFrameGroups").getJSONArray(0);var output=c.getJSONArray("actualNodeCompletedFrames").getJSONObject(0).getJSONObject("payload").getJSONObject("legacyFrame").getJSONObject("workflow_step").getJSONObject("node").getJSONObject("outputs");assertTrue(ToolSchema.same(output,CompletedModelOutputs.project(c.getJSONObject("nodeJson"),group)),c.getString("name"));}});});}
    record Fixture(CompletedOutputSources sources,RunRecord run,JSONObject task,JSONObject target,JSONArray events,List<ModelOperationRecord> rows,Map<String,List<ModelFrameRecord>> frames,Map<Integer,CheckpointRecord> checkpoints) {}
    Fixture fixture(JSONObject c){var task=ModelMessageSources.sourceObject(c.getJSONObject("assignment").toJSONString(JSONWriter.Feature.WriteMapNullValue));var node=c.getJSONObject("nodeJson");var target=DataWorkerOperationService.find(task.getJSONObject("dsl"),"node-end::e");var events=c.getJSONArray("actualEvents");var run=new RunRecord();run.setId(task.getString("runId"));run.setLeaseId(task.getString("leaseId"));run.setAttempt(task.getIntValue("attempt"));run.setWorkerId("fixture-worker");run.setWorkflowVersionId(1L);run.setSpaceId(1L);run.setOwnerUserId(42L);run.setAssignmentJson(task.toJSONString(JSONWriter.Feature.WriteMapNullValue));run.setLastEventSeq(events.stream().mapToLong(e->((JSONObject)e).getLongValue("seq")).max().orElse(0));var mapper=mock(ModelOperationMapper.class);var cpMapper=mock(CheckpointMapper.class);var rows=new ArrayList<ModelOperationRecord>();var stored=new HashMap<String,List<ModelFrameRecord>>();var checkpoints=new HashMap<Integer,CheckpointRecord>();var groups=c.getJSONArray("sourceFrameGroups");if(groups==null)groups=new JSONArray(List.of(c.getJSONArray("sourceFrames")));var calls=c.getJSONArray("actualOperations");String resource=node.getJSONObject("data").getJSONObject("nodeParam").getString("modelResourceId");var descriptor=task.getJSONObject("resourceSnapshots").getJSONObject(resource);
        for(int i=0;i<groups.size();i++){var record=new ModelOperationRecord();record.setId("actual-fixture-operation-"+i);record.setRunId(run.getId());record.setLeaseId(run.getLeaseId());record.setAttempt(run.getAttempt());record.setWorkerId(run.getWorkerId());record.setNodeId(node.getString("id"));record.setWorkflowVersionId(run.getWorkflowVersionId());record.setSpaceId(run.getSpaceId());record.setOwnerUserId(run.getOwnerUserId());record.setDslHash(task.getString("dslHash"));record.setResourceId(resource);record.setResourceVersion(descriptor.getString("version"));record.setProvider(descriptor.getString("provider"));record.setGrantAcquired(1);record.setDispatchStarted(1);record.setStopConfirmed(1);record.setStopProofId("isolated-centre-frame-finish-"+i);record.setParametersJson(calls.getJSONArray(i).getJSONObject(5).toJSONString(JSONWriter.Feature.WriteMapNullValue));record.setApprovalJson(JSONObject.of("candidate",JSONObject.of("nodeJson",node.toJSONString(JSONWriter.Feature.WriteMapNullValue))).toJSONString());var raw=groups.getJSONArray(i);var frames=new ArrayList<ModelFrameRecord>();long bytes=0;for(int j=0;j<raw.size();j++){String json=RunJsonBoundary.canonicalFull(raw.getJSONObject(j));var f=new ModelFrameRecord();f.setOperationId(record.getId());f.setSeq((long)j+1);f.setFrameJson(json);f.setFrameHash(DataRuntimeCatalog.sha(json));f.setFrameBytes(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length);bytes+=f.getFrameBytes();frames.add(f);var facts=ModelProviderWire.facts(record.getProvider(),raw.getJSONObject(j));if(facts.finish()!=null){record.setFinishSeq(f.getSeq());record.setFinishReason(facts.finish());}}record.setLastSeq((long)frames.size());record.setResponseBytes(bytes);record.setState("stop".equals(record.getFinishReason())?"COMPLETED":"FAILED");record.setFailureKind("COMPLETED".equals(record.getState())?null:"provider");rows.add(record);stored.put(record.getId(),frames);when(mapper.frames(record.getId(),0,ModelOperationJson.MAX_FRAMES)).thenReturn(frames);}
        when(mapper.forRunResource(run.getId(),resource)).thenReturn(rows);var history=c.getJSONArray("actualCheckpoints");if(history!=null)for(int i=0;i<history.size();i++){var created=history.getJSONArray(i).getJSONArray(0);var cp=new CheckpointRecord();cp.setRunId(run.getId());cp.setLeaseId(run.getLeaseId());cp.setAttempt(run.getAttempt());cp.setNodeId(node.getString("id"));cp.setOrdinal(created.getIntValue(4));cp.setQuestionJson(created.getJSONObject(5).toJSONString());for(Object value:c.getJSONArray("actualHttpResponses")){var response=(JSONObject)value;if(!response.getString("url").endsWith("/consume"))continue;var data=response.getJSONObject("envelope").getJSONObject("data");if(data.getString("checkpointId").equals(calls.getJSONArray(i).getJSONObject(5).getString("checkpointId"))){cp.setId(data.getString("checkpointId"));cp.setState(data.getString("state"));cp.setResumeDataJson(data.getJSONObject("resumeData").toJSONString());}}checkpoints.put(cp.getOrdinal(),cp);when(cpMapper.byPosition(run.getId(),run.getAttempt(),node.getString("id"),null,cp.getOrdinal())).thenReturn(cp);}
        return new Fixture(new CompletedOutputSources(null,mapper,cpMapper),run,task,target,events,rows,stored,checkpoints);
    }
    @Test void completedStateCannotAuthorizeForgedWorkerOutput() throws Exception{var c=cases().getJSONObject(0);var f=fixture(c);f.sources.verify(f.run,f.task.getJSONObject("dsl"),f.target,f.events);var changed=ModelMessageSources.sourceArray(f.events.toJSONString(JSONWriter.Feature.WriteMapNullValue));for(Object value:changed){var event=(JSONObject)value;if("node.completed".equals(event.get("eventType"))&&c.getJSONObject("nodeJson").get("id").equals(event.get("nodeId")))event.getJSONObject("payload").getJSONObject("legacyFrame").getJSONObject("workflow_step").getJSONObject("node").getJSONObject("outputs").put("first","forged write input");}assertEquals(409,assertThrows(com.ruoyi.common.exception.ServiceException.class,()->f.sources.verify(f.run,f.task.getJSONObject("dsl"),f.target,changed)).getCode());}
    @Test void missingOrChangedFrameAndUnconsumedCheckpointCannotAuthorize() throws Exception{var llm=fixture(cases().getJSONObject(0));llm.frames.get(llm.rows.getFirst().getId()).getFirst().setFrameHash("forged");assertEquals(403,assertThrows(com.ruoyi.common.exception.ServiceException.class,()->llm.sources.verify(llm.run,llm.task.getJSONObject("dsl"),llm.target,llm.events)).getCode());var qa=fixture(cases().getJSONObject(23));qa.sources.verify(qa.run,qa.task.getJSONObject("dsl"),qa.target,qa.events);qa.checkpoints.get(2).setState("RESUMED");assertEquals(403,assertThrows(com.ruoyi.common.exception.ServiceException.class,()->qa.sources.verify(qa.run,qa.task.getJSONObject("dsl"),qa.target,qa.events)).getCode());}
    private Fixture joined() throws Exception {var f=fixture(cases().getJSONObject(0));var original=cases().getJSONObject(0).getJSONObject("nodeJson");var join=JSONObject.of("id","text-joiner::middle","data",JSONObject.of("nodeParam",JSONObject.of("mode",0,"prompt","[{{value}}]"),"inputs",new JSONArray(List.of(JSONObject.of("name","value","schema",JSONObject.of("type","string","value",JSONObject.of("type","ref","content",JSONObject.of("nodeId",original.get("id"),"name","first")))))),"outputs",new JSONArray(List.of(JSONObject.of("name","output","schema",JSONObject.of("type","string"))))));var graph=f.task.getJSONObject("dsl");graph.getJSONArray("nodes").add(join);graph.put("edges",new JSONArray(List.of(JSONObject.of("sourceNodeId",original.get("id"),"targetNodeId",join.get("id")),JSONObject.of("sourceNodeId",join.get("id"),"targetNodeId",f.target.get("id")))));f.target.getJSONObject("data").put("inputs",new JSONArray(List.of(JSONObject.of("name","final","schema",JSONObject.of("type","string","value",JSONObject.of("type","ref","content",JSONObject.of("nodeId",join.get("id"),"name","output")))))));long seq=0;for(Object value:f.events){var e=(JSONObject)value;if(original.get("id").equals(e.get("nodeId"))&&"node.completed".equals(e.get("eventType")))seq=e.getLongValue("seq");}final long watermark=seq;f.events.removeIf(value->((JSONObject)value).getLongValue("seq")>watermark);var output=CompletedPureOutputs.project(join,WorkflowInputSources.values(graph,join,f.task.getJSONObject("input"),f.events));f.events.add(JSONObject.of("runId",f.run.getId(),"leaseId",f.run.getLeaseId(),"attempt",f.run.getAttempt(),"seq",seq+1,"nodeId",join.get("id"),"eventType","node.completed","payload",JSONObject.of("legacyFrame",JSONObject.of("workflow_step",JSONObject.of("node",JSONObject.of("id",join.get("id"),"outputs",output))))));f.run.setLastEventSeq(seq+1);f.run.setAssignmentJson(f.task.toJSONString(JSONWriter.Feature.WriteMapNullValue));return f;}
    @Test void actualModelToJoinerChainIsRebuiltRatherThanRejectingLegalIntermediate() throws Exception {var f=joined();f.sources.verify(f.run,f.task.getJSONObject("dsl"),f.target,f.events);}
    @Test void forgedJoinerCannotLaunderActualModelFrames() throws Exception {var f=joined();f.events.getJSONObject(f.events.size()-1).getJSONObject("payload").getJSONObject("legacyFrame").getJSONObject("workflow_step").getJSONObject("node").getJSONObject("outputs").put("output","forged intermediary");assertEquals(409,assertThrows(com.ruoyi.common.exception.ServiceException.class,()->f.sources.verify(f.run,f.task.getJSONObject("dsl"),f.target,f.events)).getCode());}
    @Test void forgedAncestorCannotBeHiddenBehindConsistentJoiner() throws Exception {var f=joined();for(Object value:f.events){var e=(JSONObject)value;if("node.completed".equals(e.get("eventType"))&&e.getString("nodeId").startsWith("spark-llm::"))e.getJSONObject("payload").getJSONObject("legacyFrame").getJSONObject("workflow_step").getJSONObject("node").getJSONObject("outputs").put("first","forged ancestor");}f.events.getJSONObject(f.events.size()-1).getJSONObject("payload").getJSONObject("legacyFrame").getJSONObject("workflow_step").getJSONObject("node").getJSONObject("outputs").put("output","[forged ancestor]");assertEquals(409,assertThrows(com.ruoyi.common.exception.ServiceException.class,()->f.sources.verify(f.run,f.task.getJSONObject("dsl"),f.target,f.events)).getCode());}
    @Test void rootAndLiteralSourcesDoNotNeedToolOrModelPorts(){var run=new RunRecord();run.setId("root");run.setLeaseId("root-lease");run.setAttempt(1);run.setLastEventSeq(0L);run.setAssignmentJson("{\"input\":{\"value\":\"actual root\"}}");var target=JSONObject.of("id","pgsql::write","data",JSONObject.of("inputs",new JSONArray(List.of(JSONObject.of("name","value","schema",JSONObject.of("type","string","value",JSONObject.of("type","ref","content",JSONObject.of("nodeId","node-start::s","name","value"))))))));new CompletedOutputSources(null,null,null).verify(run,JSONObject.of("nodes",new JSONArray(List.of(JSONObject.of("id","node-start::s","data",JSONObject.of("outputs",new JSONArray())),target)),"edges",new JSONArray()),target,new JSONArray());}
}
